"""CLI: python -m monitor <reference.csv> <current.csv> [more...]"""
import sys
import warnings


def load(path):
    with open(path) as handle:
        return [[float(x) for x in line.split(",")] for line in handle if line.strip()]


def normalize(rows):
    out = []
    for row in rows:
        norm = sum(x * x for x in row) ** 0.5
        if norm == 0:
            warnings.warn("invalid value encountered in divide", RuntimeWarning)
            out.append([float("nan") for _ in row])
        else:
            out.append([x / norm for x in row])
    return out


def main(argv):
    if len(argv) < 2:
        print("usage: monitor <reference.csv> <current.csv> [...]", file=sys.stderr)
        return 2
    reference = normalize(load(argv[0]))
    for path in argv[1:]:
        current = normalize(load(path))
        print(path, len(reference), len(current), current[0][0])
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
